// Get provider_id passed into this sub-workflow
const providerId =
  $('When Executed by Another Workflow').first().json.provider_id ?? null;

// Parsed providers.json from the previous node
const providers = $input.first().json.data;

// Validate input
if (!providerId) {
  return [
    {
      json: {
        tool: 'PROVIDER',
        status: 'INVALID_INPUT',
        provider_id: providerId,
        data: null,
        error: 'provider_id is required'
      }
    }
  ];
}

// Find the requested provider organization
const provider = providers.find(
  (record) => record.provider_id === providerId
);

// Provider not found
if (!provider) {
  return [
    {
      json: {
        tool: 'PROVIDER',
        status: 'NOT_FOUND',
        provider_id: providerId,
        data: null,
        error: 'Provider not found'
      }
    }
  ];
}

// Return organization and location facts without inferring a root cause
return [
  {
    json: {
      tool: 'PROVIDER',
      status: 'SUCCESS',
      provider_id: provider.provider_id,
      data: {
        organization_name: provider.organization_name,
        locations: provider.locations.map((location) => ({
          provider_location_id: location.provider_location_id,
          location_name: location.location_name,
          city: location.city,
          state: location.state,
          network_status: location.network_status
        }))
      },
      error: null
    }
  }
];
